import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { ChevronLeft, Plus, Calendar, ChevronDown, X } from 'lucide-react';
import './Transport.css';

const Transport = () => {
  const navigate = useNavigate();
  
  // 核心视图切换：'main' (列表/空状态) 或 'form' (预约页面)
  const [view, setView] = useState('main');
  const [activeTab, setActiveTab] = useState('Booking');
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);

  // --- 表单状态 ---
  const [pickup, setPickup] = useState('8th & Stellar');
  const [dropoff, setDropoff] = useState('Naga Emas');
  const [bookingDate, setBookingDate] = useState('2026-01-22');
  const [bookingTime, setBookingTime] = useState('');


  
  // --- 日历核心逻辑状态 ---
  // viewDate 用于控制日历当前显示的月份面板
  const [viewDate, setViewDate] = useState(new Date(2026, 0, 1)); 

  // 处理返回逻辑
  const handleBack = () => {
    if (view === 'form') {
      setView('main'); 
    } else {
      navigate('/');   
    }
  };

  // --- 日历功能函数 ---
  const changeMonth = (offset) => {
    setViewDate(new Date(viewDate.getFullYear(), viewDate.getMonth() + offset, 1));
  };

  const renderCalendarDays = () => {
    const year = viewDate.getFullYear();
    const month = viewDate.getMonth();
    
    // 获取当月第一天是周几 (0是周日, 1是周一...)
    const firstDay = new Date(year, month, 1).getDay();
    // 获取当月总天数
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    
    // 调整周一起始位偏移 (如果要周日开始则直接用 firstDay)
    const startOffset = firstDay === 0 ? 6 : firstDay - 1;
    const days = [];

    // 1. 填充月份前的空白格
    for (let i = 0; i < startOffset; i++) {
      days.push(<span key={`e-${i}`} className="day-empty"></span>);
    }

    // 2. 填充真实的日期
    for (let d = 1; d <= daysInMonth; d++) {
      // 检查当前格子的日期是否是已选中的 bookingDate
      const currentDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const isSelected = bookingDate === currentDateStr;

      days.push(
        <div 
          key={d} 
          className={`calendar-day ${isSelected ? 'selected' : ''}`}
          onClick={() => {
            setBookingDate(currentDateStr);
          }}
        >
          {d}
        </div>
      );
    }
    return days;
  };

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="transport-top-nav">
        <div className="back-arrow" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">
          {view === 'form' ? 'New Booking' : 'Transport'}
        </span>
      </nav>

      <div className="transport-main-content">
        {view === 'main' ? (
          /* --- 主界面 (列表/空状态) --- */
          <>
            <div className="transport-tabs-container">
              <div className="transport-tabs-left">
                <button className={`trans-tab ${activeTab === 'Booking' ? 'active' : ''}`} onClick={() => setActiveTab('Booking')}>Booking</button>
                <button className={`trans-tab ${activeTab === 'Timetable' ? 'active' : ''}`} onClick={() => setActiveTab('Timetable')}>Timetable</button>
              </div>
            </div>
            <div className="transport-scroll-area">
              <div className="transport-empty-state">
                <div className="empty-img-wrapper">
                  <img src="/icon_img/transportpage.png" alt="No Transport Record" />
                </div>
              </div>
            </div>
            <div className="transport-action-footer">
              <button className="new-booking-btn" onClick={() => setView('form')}>
                <Plus size={20} /> <span>New Booking</span>
              </button>
            </div>
          </>
        ) : (
          /* --- 预约子界面 --- */
          <div className="booking-form-view">
            <p className="form-intro-text">Need a ride? Book your shuttle in just one step!</p>
            
            <div className="transport-form-group">
              <label>Pick-up location *:</label>
              <div className="form-field-box select-type">
                <select value={pickup} onChange={(e) => setPickup(e.target.value)}>
                  <option value="8th & Stellar">8th & Stellar</option>
                  <option value="Main Office">Main Office</option>
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="transport-form-group">
              <label>Drop-off location *:</label>
              <div className="form-field-box select-type">
                <select value={dropoff} onChange={(e) => setDropoff(e.target.value)}>
                  <option value="Naga Emas">Naga Emas</option>
                  <option value="Train Station">Train Station</option>
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="transport-form-group">
              <label>Date:</label>
              <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                <span>{bookingDate}</span>
                <Calendar size={18} color="#666" />
              </div>
            </div>

            <div className="transport-form-group">
              <label>Time *:</label>
              <div className="form-field-box select-type">
                <select value={bookingTime} onChange={(e) => setBookingTime(e.target.value)}>
                  <option value="">Select Time</option>
                  <option value="08:00 AM">08:00 AM</option>
                  <option value="09:00 AM">09:00 AM</option>
                </select>
                <ChevronDown size={18} color="#666" className="select-arrow" />
              </div>
            </div>

            <div className="transport-form-footer">
              <button className="search-van-btn" onClick={() => alert('Searching for Van...')}>
                Search Van
              </button>
            </div>
          </div>
        )}
      </div>

      {/* 只有主界面显示底部导航 */}
       

      {/* --- 完整的日历 Overlay --- */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header">
              <span>Calendar</span>
              <button className="close-btn" onClick={() => setIsCalendarOpen(false)}><X size={20}/></button>
            </div>

            <div className="calendar-nav">
              <button className="nav-arrow" onClick={() => changeMonth(-1)}>&lt;</button>
              <span className="month-year">
                {viewDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
              </span>
              <button className="nav-arrow" onClick={() => changeMonth(1)}>&gt;</button>
            </div>

            {/* 找到 Transport.js 里的这一行，确保它包裹在正确的 className 里 */}
            <div className="weekday-row">
            {['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'].map(d => (
                <span key={d}>{d}</span>
            ))}
            </div>

            <div className="days-grid">
              {renderCalendarDays()}
            </div>

            <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>
              CONFIRM
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Transport;
